from collections import Counter

def solution(board, word):
    rows, cols = len(board), len(board[0])
    have = Counter(''.join(board))
    for ch, need in Counter(word).items():
        if have[ch] < need:
            return False                  # not enough copies of a letter: no search needed
    grid = [list(row) for row in board]   # strings are immutable; this copy can be marked

    def dfs(r, c, i):
        if grid[r][c] != word[i]:
            return False                  # prune: this branch can never match
        if i == len(word) - 1:
            return True
        grid[r][c] = '#'                  # used on the current path
        found = False
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and dfs(nr, nc, i + 1):
                found = True
                break
        grid[r][c] = word[i]              # undo, so other paths may use this cell
        return found

    for r in range(rows):
        for c in range(cols):
            if dfs(r, c, 0):              # depth at most len(word)
                return True
    return False

