def solution(board, word):
    # List every path of len(word) distinct, side-touching cells from every start,
    # and compare its letters only when the path is complete. No early pruning.
    rows, cols = len(board), len(board[0])
    size = len(word)
    for r0 in range(rows):
        for c0 in range(cols):
            stack = [[(r0, c0)]]
            while stack:
                path = stack.pop()
                if len(path) == size:
                    if ''.join(board[r][c] for r, c in path) == word:
                        return True
                    continue
                r, c = path[-1]
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in path:
                        stack.append(path + [(nr, nc)])
    return False
